svg.script:
//!export-start
var _pn_setState=0;var _pb_boolState=false;var _pn_setInterval=500;var _pc_state0Colour="#808080";var _pc_state1Colour="#22c55e";var _pc_state2Colour="#eab308";var _pc_state3Colour="#ef4444";var _pc_state4Colour="#a855f7";var _pc_state5Colour="#3b82f6";
//!export-end
function postValue(id,v){console.log("FUXA post:",id,"=",v);}
function putValue(id,v){v=Number(v);switch(id){case "_pn_setState":_pn_setState=v;var colors=[_pc_state0Colour,_pc_state1Colour,_pc_state2Colour,_pc_state3Colour,_pc_state4Colour,_pc_state5Colour];var col=colors[Math.min(v,5)]||"#808080";var els=document.querySelectorAll("g path,g circle,g rect");for(var k=0;k<els.length;k++){els[k].setAttribute("fill",col);}break;case "_pb_boolState":_pb_boolState=v!==0;var c2=_pb_boolState?_pc_state1Colour:_pc_state0Colour;var els2=document.querySelectorAll("g path,g circle,g rect");for(var j=0;j<els2.length;j++){els2[j].setAttribute("fill",c2);}break;}}
var o=new MutationObserver(function(m){m.forEach(function(mu){mu.removedNodes.forEach(function(n){if(n.id==="fuxa-dyn-blower4_flipped"){o.disconnect();}});});});o.observe(document.body,{childList:true,subtree:true});
